       OR DATALENGTH(REPLACE(REPLACE([ITL2025Level2Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ITL2025Level2Code])
       OR DATALENGTH(REPLACE(REPLACE([ITL2025Level3Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ITL2025Level3Code])
       OR DATALENGTH(REPLACE(REPLACE([Locality2020Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([Locality2020Code])
       OR DATALENGTH(REPLACE(REPLACE([Locality2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([Locality2022Code])
       OR DATALENGTH(REPLACE(REPLACE([Locality2001Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([Locality2001Code])
