    INSERT INTO #result
    SELECT N'postcode_simd', N'columns declared and in order', N'0 differences',
           CONVERT(nvarchar(200), COUNT(*)) + N' differences', COUNT(*), CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
    FROM (
        SELECT d.name FROM @declared_main d
        LEFT JOIN INFORMATION_SCHEMA.COLUMNS c
               ON c.TABLE_NAME = PARSENAME(N'postcode_simd', 1) AND c.COLUMN_NAME = d.name
              AND c.ORDINAL_POSITION = d.ordinal AND c.DATA_TYPE = d.type_name
              AND c.IS_NULLABLE = CASE d.is_nullable WHEN 1 THEN 'YES' ELSE 'NO' END
        WHERE c.COLUMN_NAME IS NULL
        UNION ALL
        SELECT c.COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS c
        WHERE c.TABLE_NAME = PARSENAME(N'postcode_simd', 1)
          AND c.COLUMN_NAME NOT IN (SELECT name FROM @declared_main)
    ) AS differences;

    -- 2. The natural key, which the digest also cannot see: it is order independent, so a
    -- duplicated row and a missing one can cancel out.
    INSERT INTO #result
    SELECT N'postcode_simd', N'natural key [pc_norm] unique and not null', N'0 offending rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' offending rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM (SELECT [pc_norm] FROM postcode_simd GROUP BY [pc_norm] HAVING COUNT_BIG(*) > 1) AS duplicates;

    -- 3. Reserved characters in the text columns. The digest frames fields with them, so text
    -- containing one could make two different rows hash alike. The export refuses them; so does
    -- this. A rendered null is legitimately NCHAR(0), which is why this reads the columns.
    INSERT INTO #result
    SELECT N'postcode_simd', N'no reserved framing characters in text', N'0 rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM postcode_simd
    WHERE DATALENGTH(REPLACE(REPLACE([Postcode] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([Postcode])
       OR DATALENGTH(REPLACE(REPLACE([PostcodeDistrict] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PostcodeDistrict])
       OR DATALENGTH(REPLACE(REPLACE([PostcodeSector] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PostcodeSector])
