       OR DATALENGTH(REPLACE(REPLACE([LinkedSmallUserPostcode] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LinkedSmallUserPostcode])
