       OR DATALENGTH(REPLACE(REPLACE([DateOfDeletion] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DateOfDeletion])
       OR DATALENGTH(REPLACE(REPLACE([PostcodeType] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([PostcodeType])
       OR DATALENGTH(REPLACE(REPLACE([OutputArea2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OutputArea2022Code])
       OR DATALENGTH(REPLACE(REPLACE([OutputArea2011Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OutputArea2011Code])
       OR DATALENGTH(REPLACE(REPLACE([DataZone2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DataZone2022Code])
       OR DATALENGTH(REPLACE(REPLACE([DataZone2011Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DataZone2011Code])
       OR DATALENGTH(REPLACE(REPLACE([IntermediateZone2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IntermediateZone2022Code])
       OR DATALENGTH(REPLACE(REPLACE([IntermediateZone2011Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IntermediateZone2011Code])
       OR DATALENGTH(REPLACE(REPLACE([OutputArea2001Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OutputArea2001Code])
       OR DATALENGTH(REPLACE(REPLACE([DataZone2001Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([DataZone2001Code])
       OR DATALENGTH(REPLACE(REPLACE([IntermediateZone2001Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IntermediateZone2001Code])
       OR DATALENGTH(REPLACE(REPLACE([OutputArea1991Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OutputArea1991Code])
       OR DATALENGTH(REPLACE(REPLACE([CouncilArea2019Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CouncilArea2019Code])
       OR DATALENGTH(REPLACE(REPLACE([RegistrationDistrict2007Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([RegistrationDistrict2007Code])
       OR DATALENGTH(REPLACE(REPLACE([LocalGovernmentDistrict1995Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LocalGovernmentDistrict1995Code])
       OR DATALENGTH(REPLACE(REPLACE([LocalGovernmentDistrict1991Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LocalGovernmentDistrict1991Code])
       OR DATALENGTH(REPLACE(REPLACE([ElectoralWard2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ElectoralWard2022Code])
       OR DATALENGTH(REPLACE(REPLACE([ScottishParliamentaryRegion2026Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ScottishParliamentaryRegion2026Code])
       OR DATALENGTH(REPLACE(REPLACE([ScottishParliamentaryConstituency2026Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ScottishParliamentaryConstituency2026Code])
       OR DATALENGTH(REPLACE(REPLACE([UKParliamentaryConstituency2024Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([UKParliamentaryConstituency2024Code])
       OR DATALENGTH(REPLACE(REPLACE([HealthBoardArea2019Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([HealthBoardArea2019Code])
       OR DATALENGTH(REPLACE(REPLACE([HealthBoardArea2006Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([HealthBoardArea2006Code])
       OR DATALENGTH(REPLACE(REPLACE([HealthBoardArea1995Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([HealthBoardArea1995Code])
       OR DATALENGTH(REPLACE(REPLACE([IntegrationAuthority2019Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IntegrationAuthority2019Code])
       OR DATALENGTH(REPLACE(REPLACE([StrategicDevelopmentPlanningArea2013Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([StrategicDevelopmentPlanningArea2013Code])
       OR DATALENGTH(REPLACE(REPLACE([CivilParish1930Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CivilParish1930Code])
       OR DATALENGTH(REPLACE(REPLACE([TravelToWorkArea2011Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([TravelToWorkArea2011Code])
       OR DATALENGTH(REPLACE(REPLACE([IslandCode] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IslandCode])
       OR DATALENGTH(REPLACE(REPLACE([UrbanRural6Fold2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([UrbanRural6Fold2022Code])
       OR DATALENGTH(REPLACE(REPLACE([UrbanRural8Fold2022Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([UrbanRural8Fold2022Code])
       OR DATALENGTH(REPLACE(REPLACE([LAU2025Level1Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LAU2025Level1Code])
       OR DATALENGTH(REPLACE(REPLACE([ITL2025Level2Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ITL2025Level2Code])
       OR DATALENGTH(REPLACE(REPLACE([ITL2025Level3Code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ITL2025Level3Code])
       OR DATALENGTH(REPLACE(REPLACE([CensusHouseholdCount2022] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusHouseholdCount2022])
       OR DATALENGTH(REPLACE(REPLACE([CensusPopulationCount2022] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusPopulationCount2022])
       OR DATALENGTH(REPLACE(REPLACE([CensusHouseholdCount2011] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusHouseholdCount2011])
       OR DATALENGTH(REPLACE(REPLACE([CensusPopulationCount2011] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusPopulationCount2011])
       OR DATALENGTH(REPLACE(REPLACE([CensusHouseholdCount2001] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusHouseholdCount2001])
       OR DATALENGTH(REPLACE(REPLACE([CensusPopulationCount2001] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusPopulationCount2001])
       OR DATALENGTH(REPLACE(REPLACE([CensusHouseholdCount1991] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusHouseholdCount1991])
       OR DATALENGTH(REPLACE(REPLACE([CensusPopulationCount1991] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CensusPopulationCount1991])
       OR DATALENGTH(REPLACE(REPLACE([ScottishIndexOfMultipleDeprivation2020Rank] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ScottishIndexOfMultipleDeprivation2020Rank])
       OR DATALENGTH(REPLACE(REPLACE([pc_norm] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([pc_norm])
       OR DATALENGTH(REPLACE(REPLACE([spd_user_type] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([spd_user_type])
       OR DATALENGTH(REPLACE(REPLACE([sspl_release] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([sspl_release])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2001_hb] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2001_hb])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2001_hscp] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2001_hscp])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2001_ca] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2001_ca])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2011_hb] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2011_hb])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2011_hscp] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2011_hscp])
       OR DATALENGTH(REPLACE(REPLACE([phs_dz2011_ca] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([phs_dz2011_ca]);

    -- 4. The digest. Each row is rendered as the CSV renders it, with NCHAR(0) for a null so a
    -- null and a blank differ, the fields joined with NCHAR(31) in contract order, converted to
    -- UTF-8 and hashed. The signed eight-byte prefixes are summed as decimal: converting after
    -- SUM would be too late, because SUM over bigint can overflow.
    INSERT INTO #result
    SELECT N'postcode_simd', N'row count', CONVERT(nvarchar(200), e.row_count),
           CONVERT(nvarchar(200), q.n), ABS(q.n - e.row_count),
           CASE WHEN q.n = e.row_count THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (SELECT COUNT_BIG(*) AS n FROM postcode_simd) AS q
    WHERE e.name = N'postcode_simd';

    INSERT INTO #result
    SELECT N'postcode_simd', N'row digest, definition version ' + CONVERT(nvarchar(10), e.digest_version),
           CONVERT(nvarchar(200), e.digest_total), CONVERT(nvarchar(200), ISNULL(q.total, 0)),
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 0 ELSE 1 END,
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (
        SELECT SUM(CONVERT(decimal(38,0), CONVERT(bigint, SUBSTRING(HASHBYTES('SHA2_256',
                   CONVERT(varchar(max), CONCAT_WS(NCHAR(31),
           CONVERT(nvarchar(max), ISNULL([Postcode], NCHAR(0))),
           ISNULL([PostcodeDistrict], NCHAR(0)),
           ISNULL([PostcodeSector], NCHAR(0)),
           ISNULL([SplitIndicator], NCHAR(0)),
           ISNULL([LinkedSmallUserPostcode], NCHAR(0)),
           ISNULL([DateOfIntroduction], NCHAR(0)),
           ISNULL([DateOfDeletion], NCHAR(0)),
           ISNULL([PostcodeType], NCHAR(0)),
           ISNULL([OutputArea2022Code], NCHAR(0)),
           ISNULL([OutputArea2011Code], NCHAR(0)),
           ISNULL([DataZone2022Code], NCHAR(0)),
           ISNULL([DataZone2011Code], NCHAR(0)),
           ISNULL([IntermediateZone2022Code], NCHAR(0)),
           ISNULL([IntermediateZone2011Code], NCHAR(0)),
           ISNULL([OutputArea2001Code], NCHAR(0)),
           ISNULL([DataZone2001Code], NCHAR(0)),
           ISNULL([IntermediateZone2001Code], NCHAR(0)),
           ISNULL([OutputArea1991Code], NCHAR(0)),
           ISNULL([CouncilArea2019Code], NCHAR(0)),
           ISNULL([RegistrationDistrict2007Code], NCHAR(0)),
           ISNULL([LocalGovernmentDistrict1995Code], NCHAR(0)),
           ISNULL([LocalGovernmentDistrict1991Code], NCHAR(0)),
           ISNULL([ElectoralWard2022Code], NCHAR(0)),
           ISNULL([ScottishParliamentaryRegion2026Code], NCHAR(0)),
           ISNULL([ScottishParliamentaryConstituency2026Code], NCHAR(0)),
           ISNULL([UKParliamentaryConstituency2024Code], NCHAR(0)),
           ISNULL([HealthBoardArea2019Code], NCHAR(0)),
           ISNULL([HealthBoardArea2006Code], NCHAR(0)),
           ISNULL([HealthBoardArea1995Code], NCHAR(0)),
           ISNULL([IntegrationAuthority2019Code], NCHAR(0)),
           ISNULL([StrategicDevelopmentPlanningArea2013Code], NCHAR(0)),
           ISNULL([CivilParish1930Code], NCHAR(0)),
